use super::*;

pub(crate) fn describe(s: &Socket) -> ExposedSocket {
    ExposedSocket {
        transport: match s.transport {
            Protocol::Tcp => "tcp".to_string(),
            Protocol::Udp => "udp".to_string(),
        },
        addr: s.local_addr.clone(),
        port: s.local_port,
    }
}
